using System;using System.IO;using System.IO.Compression;using System.Xml.Linq;using System.Linq;using System.Collections.Generic;using V15Update;
public static class UpdaterTests {
 static int count;static void Check(bool yes,string name){if(!yes)throw new Exception("FAIL "+name);count++;Console.WriteLine("PASS "+name);}static void Reject(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception("FAIL "+name);}
 static void Text(string root,string path,string value){string full=Path.Combine(root,path);Directory.CreateDirectory(Path.GetDirectoryName(full));File.WriteAllText(full,value);}
 static string Package(string dir,string path="V15VoiceStudio.exe",bool corrupt=false){string pack=Path.Combine(dir,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(pack);Text(pack,"payload/"+path,"new app");Text(pack,"payload/V15Updater.exe","new updater");var manifest=new XElement("update",new XAttribute("product","V15VoiceStudio"),new XAttribute("version","1.4.1"),new XAttribute("kind","core"),new XAttribute("space","0"));foreach(string name in new[]{path,"V15Updater.exe"})manifest.Add(new XElement("file",new XAttribute("path",name),new XAttribute("size",new FileInfo(Path.Combine(pack,"payload",name)).Length),new XAttribute("sha256",UpdateEngine.Hash(Path.Combine(pack,"payload",name)))));manifest.Save(Path.Combine(pack,"manifest.xml"));if(corrupt)Text(pack,"payload/"+path,"damaged");string zip=pack+".zip";ZipFile.CreateFromDirectory(pack,zip);return zip;}
 public static void Main(){string root=Path.Combine(Path.GetTempPath(),"V15_updater_tests_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  foreach(string path in new[]{"../escape","source/../../escape","/absolute","C:/drive","source/a\\b","source/CON.txt","source/name.","source/a:b"})Reject(()=>UpdateEngine.Safe(root,path),"Reject unsafe Windows path "+path);
  string pack=Package(root),stage=Path.Combine(root,"stage");var files=UpdateEngine.Stage(pack,stage,s=>{});Check(files.Count==2&&File.ReadAllText(Path.Combine(stage,"V15VoiceStudio.exe"))=="new app","Valid ZIP stages and verifies every payload hash");
  Reject(()=>UpdateEngine.Stage(Package(root,corrupt:true),Path.Combine(root,"corrupt"),s=>{}),"Corrupt ZIP payload rejected before modifying installed app");
  Reject(()=>UpdateEngine.Stage(Package(root,"user_voices/voices.xml"),Path.Combine(root,"forbidden"),s=>{}),"Core updates cannot replace user voice data");
  string target=Path.Combine(root,"app");Directory.CreateDirectory(target);Text(target,"V15VoiceStudio.exe","old app");Text(target,"my_script.srt","KEEP SCRIPT");Text(target,"user_voices/sample.wav","KEEP VOICE");UpdateEngine.Commit(stage,target,files,s=>{});Check(File.ReadAllText(Path.Combine(target,"V15VoiceStudio.exe"))=="new app"&&File.ReadAllText(Path.Combine(target,"V15Updater.exe"))=="new updater","Commit replaces the app and adds new release files");Check(File.ReadAllText(Path.Combine(target,"my_script.srt"))=="KEEP SCRIPT"&&File.ReadAllText(Path.Combine(target,"user_voices/sample.wav"))=="KEEP VOICE","Commit preserves scripts and private reference voices");
  Text(target,"V15VoiceStudio.exe","original app");File.Delete(Path.Combine(target,"V15Updater.exe"));files=UpdateEngine.Stage(pack,Path.Combine(root,"rollback"),s=>{});Reject(()=>UpdateEngine.Commit(Path.Combine(root,"rollback"),target,files,s=>{},i=>{if(i==2)throw new IOException("simulated failure");}),"Mid-commit failure triggers rollback");Check(File.ReadAllText(Path.Combine(target,"V15VoiceStudio.exe"))=="original app"&&!File.Exists(Path.Combine(target,"V15Updater.exe")),"Rollback restores previous executable and removes newly added files");Check(!File.Exists(Path.Combine(target,".v15-update-journal.xml")),"Successful rollback clears the recovery journal");
  string backup=".v15-backup-test";Text(target,backup+"/V15VoiceStudio.exe","before crash");Text(target,"V15VoiceStudio.exe","after crash");Text(target,"new.dat","new after crash");var journal=new XElement("transaction",new XAttribute("backup",backup),new XElement("file",new XAttribute("path","V15VoiceStudio.exe"),new XAttribute("old","1"),new XAttribute("ready","1"),new XAttribute("newHash",UpdateEngine.Hash(Path.Combine(target,"V15VoiceStudio.exe")))),new XElement("file",new XAttribute("path","new.dat"),new XAttribute("old","0"),new XAttribute("ready","1"),new XAttribute("newHash",UpdateEngine.Hash(Path.Combine(target,"new.dat")))));journal.Save(Path.Combine(target,".v15-update-journal.xml"));UpdateEngine.Recover(target);Check(File.ReadAllText(Path.Combine(target,"V15VoiceStudio.exe"))=="before crash"&&!File.Exists(Path.Combine(target,"new.dat")),"Next update can recover a transaction interrupted by process termination");
  string gpu=Path.Combine(root,"gpu");Directory.CreateDirectory(gpu);new XElement("update",new XAttribute("product","V15VoiceStudio"),new XAttribute("version","1.4.1"),new XAttribute("kind","gpu"),new XElement("wheel",new XAttribute("name","torch.whl")),new XElement("wheel",new XAttribute("name","torchaudio.whl"))).Save(Path.Combine(gpu,"manifest.xml"));Reject(()=>UpdateEngine.Stage(gpu,Path.Combine(root,"gpu-stage"),s=>{}),"Incomplete GPU package fails without touching installed runtime");
  string crash=Path.Combine(root,"crash-app");Directory.CreateDirectory(Path.Combine(crash,"ai","models"));Text(crash,"ai/runtime/python.exe","fixture");string originalExe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"V15VoiceStudio.exe"),oldExe=Path.Combine(crash,".v15-backup-crash","V15VoiceStudio.exe");Directory.CreateDirectory(Path.GetDirectoryName(oldExe));File.Copy(originalExe,oldExe);new XElement("transaction",new XAttribute("backup",".v15-backup-crash"),new XElement("file",new XAttribute("path","V15VoiceStudio.exe"),new XAttribute("old","1"),new XAttribute("ready","1"),new XAttribute("newHash","none"))).Save(Path.Combine(crash,".v15-update-journal.xml"));
  Text(crash,".v15-stage-interrupted/.v15-owner","V15VoiceStudio");Text(crash,".v15-stage-interrupted/partial.bin","temporary data");
  Reject(()=>UpdateEngine.Apply(pack,crash,x=>{}),"Invalid next package still fails after automatic recovery");Check(File.Exists(Path.Combine(crash,"V15VoiceStudio.exe"))&&UpdateEngine.Hash(Path.Combine(crash,"V15VoiceStudio.exe"))==UpdateEngine.Hash(originalExe),"Apply recovers the app even if power failed between old and new EXE moves");Check(!Directory.Exists(Path.Combine(crash,".v15-stage-interrupted")),"Retry cleans only marked interrupted staging folders before checking space");
  Console.WriteLine("TOTAL UPDATER "+count+" passed.");
 }
}
